import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # Build per-account list of version dicts from the existing dimension state.
    accounts = {}
    for _, row in dim.iterrows():
        acc = row["account_id"]
        ver = {
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": row["is_current"],
        }
        accounts.setdefault(acc, []).append(ver)

    def same_plan(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na or b_na:
            return False
        return a == b

    # Process staged records in (account_id, update_date) order, each one
    # seeing the effects of earlier ones.
    stg_sorted = stg.sort_values(["account_id", "update_date"], kind="mergesort")

    for _, s in stg_sorted.iterrows():
        acc = s["account_id"]
        plan = s["plan"]
        upd = s["update_date"]

        versions = accounts.setdefault(acc, [])

        if not versions:
            versions.append({
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
            continue

        # Find the version covering update_date: start <= upd < end (end NULL = open)
        cover = None
        for v in versions:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= upd and (pd.isna(end) or upd < end):
                cover = v
                break

        if cover is None:
            # update_date is earlier than the account's first version
            f = min(versions, key=lambda v: v["eff_start_date"])
            versions.append({
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            if same_plan(cover["plan"], plan):
                pass
            elif upd == cover["eff_start_date"]:
                cover["plan"] = plan
            else:
                versions.append({
                    "plan": plan,
                    "eff_start_date": upd,
                    "eff_end_date": cover["eff_end_date"],
                    "is_current": cover["is_current"],
                })
                cover["eff_end_date"] = upd
                cover["is_current"] = 0

    rows = []
    for acc, versions in accounts.items():
        for v in versions:
            rows.append({
                "account_id": acc,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out = out.sort_values(["account_id", "eff_start_date"], kind="mergesort").reset_index(drop=True)
        out["account_id"] = out["account_id"].astype("int64")
        out["is_current"] = out["is_current"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    else:
        out = pd.DataFrame(
            columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"]
        )
        out["account_id"] = out["account_id"].astype("int64")
        out["is_current"] = out["is_current"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])

    return {"dim_account_out": out}
